/**
 * data/b3/division-with-remainder.js — the G3-377 `division-with-remainder`
 * bank ×11. EN block hand-authored (2026-09-14, the G3-377 build session); the
 * ten non-EN blocks are GENERATED by tools/apply-b3-locale.js from
 * i18n/.draft-b3-<loc>.json after tools/validate-b3-draft.js (never hand-edit a
 * non-EN block here). Contract: docs/worksheet-gen/b3-designs/
 * G3-377-division-with-remainder.md §5. Read at render ONLY through
 * lib/b3-common.js `bank('division-with-remainder', loc)`.
 *
 * The content of this type is NUMERIC: every item is n = q·d + r with
 * 0 < r < d, drawn in code and shared by every locale; a pile is COUNTED,
 * never named, so no noun ever enters a sentence. A locale block carries:
 *   exemplar    the divisor set a unit-less build() fans over ('2-5' | '6-9' |
 *               '2-9'; the README's ONE fan mechanism, unitAxis).
 *   unitLabels  the spoken form of each unit for a {U} title token ("by 2 to
 *               5"); optional — a missing label falls back to the unit key.
 *   notation    op: the locale's division sign ('÷' | ':' | '/' | null for a
 *               product form) — it MUST agree with types/_shared/notation.js
 *               divGlyph(loc) (the ONE sign table; sv MUST be '/', never '÷',
 *               a historic Swedish MINUS); template: each of {n}{d}{q}{r}
 *               exactly once, no digit, glyphs only from `÷ : / × · = + , ( )`;
 *               boxStyle 'inline' | 'casita' (es galera / pt chave / it
 *               colonna); remWord (0..8 chars) printed before the r box;
 *               exactWord + restWord (the F3 pills — both, or F3 is REFUSED
 *               in the locale); leftoverLabel (the F1 leftover home — or F1
 *               is refused); rightWord / wrongWord (F4 d3 pills, distinct);
 *               kinds {quotative, partitive} where the locale names both
 *               kinds of division, else null.
 *   strings     per-face title + instruction (G3-377 = the base; F1..F5 the
 *               faces of §3): title <= 70, no worksheet-word, unique in the
 *               band, never the bare family head; instruction <= 150 with an
 *               end mark; no visible "free" claim; {U} may appear in a title.
 *
 * validateBank(all) implements every §5 validator rule (the division block of
 * tools/validate-b3-draft.js) and is what the gate and the apply tool import;
 * it returns { fails:[], notes:[] } — a refusal (F1 / F3 withheld in a locale)
 * is a NOTE the hub-gate expectation reads, never a silent pass.
 */
'use strict';

const DIVISION = {
  en: {
    exemplar: '2-5',
    unitLabels: { '2-5': 'by 2 to 5', '6-9': 'by 6 to 9', '2-9': 'by 2 to 9' },
    notation: {
      op: '÷',
      template: '{n} ÷ {d} = {q} R{r}',
      boxStyle: 'inline',
      remWord: 'R',
      exactWord: 'exact',
      restWord: 'remainder',
      leftoverLabel: 'left over',
      rightWord: 'right',
      wrongWord: 'wrong',
      kinds: { quotative: 'grouping', partitive: 'sharing' },
    },
    strings: {
      'G3-377': {
        title: 'Division with Remainders: Ring the Groups',
        instruction: 'Ring groups of the second number in each pile. Write how many groups you made and how many pictures are left over.',
      },
      F1: {
        title: 'Share It Out: What Is Left Over?',
        instruction: 'Deal the pile into the boxes one at a time. Write how many each box gets and how many cannot be shared.',
      },
      F2: {
        title: 'Division with Remainders: Practice Rows',
        instruction: 'Every division leaves something over. Write the answer and the remainder in each row.',
      },
      F3: {
        title: 'Exact or Not? Divisions With and Without a Remainder',
        instruction: 'Decide whether each division comes out exactly. Circle your choice and write the remainder, 0 if there is none.',
      },
      F4: {
        title: 'Find the Error: The Remainder Is Too Big',
        instruction: 'Every division has been worked out wrongly. Cross out the wrong numbers and write the right answer and remainder in the boxes.',
      },
      F5: {
        title: 'Hop Back on the Number Line: What Is Left?',
        instruction: 'Start at the marked number and draw hops back of the same size until a whole hop no longer fits. Write the hops and where you land.',
      },
    },
  },
};

/* ---------------------------------------------------------------- validator (§5) */
const FACES = ['G3-377', 'F1', 'F2', 'F3', 'F4', 'F5'];
const UNITS = ['2-5', '6-9', '2-9'];
const OPS = ['÷', ':', '/', null];
const BOX_STYLES = ['inline', 'casita'];
const GLYPHS = new Set(['÷', ':', '/', '×', '·', '=', '+', ',', '(', ')']);
const SLOT_RE = /\{[ndqr]\}/g;
const WORKSHEET_WORD = /(?<!\p{L})(worksheet|arbeitsblatt|hoja de trabajo|folha de exerc\p{L}*|fiche|scheda|werkblad|arbetsblad|arbejdsark|arbeidsark|tehtäväpaperi|tehtäväsivu)(?!\p{L})/iu;
/** The bare family head per locale (§1): a face title equal to it FAILS (rule 6). */
const HEAD = {
  en: 'Division with Remainders', de: 'Teilen mit Rest', es: 'Divisiones con residuo', pt: 'Divisão com resto', fr: 'Division avec reste',
  it: 'Divisioni con il resto', nl: 'Delen met rest', sv: 'Division med rest', da: 'Division med rest', no: 'Divisjon med rest', fi: 'Jakojäännös',
};
/** Titles of the shipped G3-309 / G3-310 / G3-370 landings (en; a panel adds its locale's) — a face title equal to one FAILS (rule 6). */
const SIBLING_TITLES = {
  en: ['Divide It Up', 'Repeated Subtraction Division', 'Multiplication and Division Word Problems'],
};
function fold(s) { return String(s).trim().toLowerCase().replace(/[:!?.]+$/, '').normalize('NFD').replace(/[̀-ͯ]/g, ''); }

/**
 * §5 rules over the whole bank (or one block via {loc: block}). Returns
 * { fails, notes }: fails = exit 1 for the validator; notes = refusals the
 * hub-gate expectation must read (F1 without leftoverLabel, F3 without both
 * pill words).
 */
function validateBank(all, opts) {
  const { divGlyph, mulGlyph } = require('../../types/_shared/notation.js');
  const freeClaim = require('../../../lib/free-claim.js');
  const fails = [], notes = [];
  const locs = Object.keys(all || {});
  if (!locs.length) fails.push('bank: no locale block at all');
  for (const loc of locs) {
    const B = all[loc];
    const N = B && B.notation;
    const P = `${loc}:`;
    if (!B || typeof B !== 'object') { fails.push(`${P} block is not an object`); continue; }
    if (!UNITS.includes(B.exemplar)) fails.push(`${P} exemplar "${B.exemplar}" is not a unit (${UNITS.join(' | ')})`);
    if (B.unitLabels) for (const u of Object.keys(B.unitLabels)) if (!UNITS.includes(u)) fails.push(`${P} unitLabels names an unknown unit "${u}"`);
    if (!N || typeof N !== 'object') { fails.push(`${P} notation block missing`); continue; }
    // (1) template
    const tpl = String(N.template || '');
    for (const s of ['{n}', '{d}', '{q}', '{r}']) {
      const c = (tpl.match(new RegExp(s.replace(/[{}]/g, '\\$&'), 'g')) || []).length;
      if (c !== 1) fails.push(`${P} template carries ${s} ${c} times, want exactly once: "${tpl}"`);
    }
    if (/\d/.test(tpl)) fails.push(`${P} template carries a digit: "${tpl}"`);
    const rest = tpl.replace(SLOT_RE, '').replace(/\s+/g, '');
    for (const ch of rest) if (!GLYPHS.has(ch) && !/\p{L}|[.]/u.test(ch)) fails.push(`${P} template glyph "${ch}" outside \`÷ : / × · = + , ( )\`: "${tpl}"`);
    if (!tpl.includes('=')) fails.push(`${P} template has no "=": "${tpl}"`);
    // (2) op in the enum; op non-null -> template contains it
    if (!OPS.includes(N.op === undefined ? 'MISSING' : N.op)) fails.push(`${P} op "${N.op}" not in ÷ | : | / | null`);
    if (N.op && !tpl.includes(N.op)) fails.push(`${P} op "${N.op}" is not in the template "${tpl}"`);
    if (N.op === null && !/[×·]/.test(tpl)) fails.push(`${P} op null (product form) but the template has no × / ·: "${tpl}"`);
    // (9) the sign agrees with types/_shared/notation.js — the ONE sign table (README item 11)
    if (N.op && N.op !== divGlyph(loc)) fails.push(`${P} op "${N.op}" disagrees with notation.js divGlyph(${loc}) = "${divGlyph(loc)}"`);
    for (const g of ['÷', ':', '/']) if (g !== divGlyph(loc) && tpl.includes(g)) fails.push(`${P} template prints "${g}", the ${loc} division sign is "${divGlyph(loc)}"`);
    for (const g of ['×', '·']) if (g !== mulGlyph(loc) && tpl.includes(g)) fails.push(`${P} template prints "${g}", the ${loc} product sign is "${mulGlyph(loc)}"`);
    // (3) sv: op === '/' and no string anywhere in the block contains ÷ (a historic Swedish MINUS)
    if (loc === 'sv') {
      if (N.op !== '/') fails.push(`sv: op must be "/" (÷ is a historic Swedish minus), got "${N.op}"`);
      const walk = (v, path) => {
        if (typeof v === 'string') { if (v.includes('÷')) fails.push(`sv: "${path}" contains ÷ (historic minus)`); }
        else if (v && typeof v === 'object') for (const k of Object.keys(v)) walk(v[k], path + '.' + k);
      };
      walk(B, 'sv');
    }
    // (4) words
    const remWord = N.remWord == null ? '' : String(N.remWord);
    if ([...remWord].length > 8) fails.push(`${P} remWord "${remWord}" > 8 chars`);
    if (/\d/.test(remWord)) fails.push(`${P} remWord carries a digit`);
    if (!(N.exactWord && N.restWord)) notes.push(`${loc}: F3 REFUSED (exactWord + restWord not both authored)`);
    if (N.exactWord && N.restWord && fold(N.exactWord) === fold(N.restWord)) fails.push(`${P} exactWord === restWord`);
    if (!N.leftoverLabel) notes.push(`${loc}: F1 REFUSED (leftoverLabel not authored)`);
    // (5) boxStyle; casita locales still carry all four slots (checked by rule 1 already)
    if (!BOX_STYLES.includes(N.boxStyle)) fails.push(`${P} boxStyle "${N.boxStyle}" not in inline | casita`);
    // (7) kinds null or both keys
    if (N.kinds !== null && N.kinds !== undefined) {
      if (typeof N.kinds !== 'object' || !N.kinds.quotative || !N.kinds.partitive) fails.push(`${P} kinds must be null or {quotative, partitive}`);
    }
    // (8) rightWord !== wrongWord
    if (N.rightWord && N.wrongWord && fold(N.rightWord) === fold(N.wrongWord)) fails.push(`${P} rightWord === wrongWord`);
    // (6) strings
    const S = B.strings || {};
    const titles = [];
    const head = fold(HEAD[loc] || '');
    const sibs = new Set((SIBLING_TITLES[loc] || []).map(fold));
    for (const f of FACES) {
      const s = S[f];
      if (!s || !s.title || !s.instruction) { fails.push(`${P} strings.${f} missing title/instruction`); continue; }
      if ([...s.title].length > 70) fails.push(`${P} ${f} title ${[...s.title].length} > 70`);
      if (WORKSHEET_WORD.test(s.title)) fails.push(`${P} ${f} title carries the worksheet word`);
      if (head && fold(s.title) === head) fails.push(`${P} ${f} title "${s.title}" equals the family head bare`);
      if (sibs.has(fold(s.title))) fails.push(`${P} ${f} title "${s.title}" equals a shipped G3-309 / G3-310 / G3-370 landing title`);
      if ([...s.instruction].length > 150) fails.push(`${P} ${f} instruction ${[...s.instruction].length} > 150`);
      if (!/[.!?]$/.test(s.instruction.trim())) fails.push(`${P} ${f} instruction has no end mark`);
      const slots = (s.title + ' ' + s.instruction).match(/\{[^}]*\}/g) || [];
      for (const sl of slots) if (!/^\{(U|L|UNIT)\}$/.test(sl)) fails.push(`${P} ${f} carries a slot ${sl} (the apparatus is language-free)`);
      const claim = freeClaim.hit(s.title + ' ' + s.instruction);
      if (claim) fails.push(`${P} ${f} visible copy claims free ("${claim}")`);
      if (loc === 'sv' && /÷/.test(s.title + s.instruction)) fails.push(`sv: ${f} string contains ÷`);
      titles.push(fold(s.title));
    }
    if (new Set(titles).size !== titles.length) fails.push(`${P} face titles repeat`);
  }
  return { fails, notes };
}

module.exports = { DIVISION, validateBank, FACES, UNITS, HEAD };
